"""Object-oriented coverage (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class OopTests(unittest.TestCase):

    def test_001_class_basic(self):
        source = """\
CLASS E01Counter
VAR
Count : INT;
END_VAR
METHOD PUBLIC Increment : INT
VAR_INPUT
Delta : INT;
END_VAR
Count := Count + Delta;
Increment := Count;
END_METHOD
END_CLASS
PROGRAM E01Prog
VAR C : E01Counter; R : INT; END_VAR
R := C.Increment(2);
END_PROGRAM
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('E01Counter', c_result.output)
        self.assertIn('Increment', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('E01Counter', rust_result.output)
        self.assertIn('Increment', rust_result.output)

